### Validation Rules

```typescript
function validateGenomeSpec(spec: GenomeSpec): ValidationResult {
    const errors: ValidationError[] = [];
    const warnings: ValidationWarning[] = [];

    // Required for any useful genome
    if (!spec.displayName) errors.push({ field: 'displayName', message: 'required' });
    if (!spec.baseRoleId && !spec.systemPrompt) {
        errors.push({ field: 'baseRoleId|systemPrompt', message: 'at least one required' });
    }

    // Runtime type validation
    if (spec.runtimeType && !['claude', 'codex', 'open-code'].includes(spec.runtimeType)) {
        errors.push({ field: 'runtimeType', message: 'must be claude, codex, or open-code' });
    }

    // Memory type validation
    if (spec.memory?.type && !['session', 'persistent', 'shared'].includes(spec.memory.type)) {
        errors.push({ field: 'memory.type', message: 'must be session, persistent, or shared' });
    }

    // Warnings for better marketplace discoverability
    if (!spec.tags?.length) warnings.push({ field: 'tags', message: 'no tags — poor marketplace search' });
    if (!spec.capabilities?.length) warnings.push({ field: 'capabilities', message: 'no capabilities — scoring engine cannot match' });
    if (!spec.category) warnings.push({ field: 'category', message: 'no category — won\'t appear in category filters' });
    if (!spec.description) warnings.push({ field: 'description', message: 'no description — users can\'t evaluate' });

    // Layer coverage check
    const layerCoverage = {
        runtime: !!(spec.runtimeType || spec.modelId || spec.systemPrompt),
        collaboration: !!(spec.messaging || spec.behavior || spec.teamRole),
        memory: !!(spec.memory),
        governance: !!(spec.capabilities || spec.scopeOfResponsibility || spec.modelScores),
        resume: !!(spec.resume),
        operations: !!(spec.operations),
    };

    return { 
        valid: errors.length === 0, 
        errors, 
        warnings,
        computed: { 
            runtimeType: spec.runtimeType ?? 'claude',
            layerCoverage 
        }
    };
}
```

