### 3. Agent 排序函数（可直接复制）

```typescript
// sources/utils/matrixSort.ts

import type { KanbanTeamMember } from '@/sync/kanbanTypes';
import { getAgentPresenceVisual } from '@/utils/sessionUtils';

export type AgentTier = 'meta' | 'coordinator' | 'worker';

const META_ROLES = new Set(['supervisor', 'org-manager', 'help-agent']);
const COORDINATOR_ROLES = new Set(['master']);

export function getAgentTier(roleId: string): AgentTier {
  if (META_ROLES.has(roleId)) return 'meta';
  if (COORDINATOR_ROLES.has(roleId)) return 'coordinator';
  return 'worker';
}

const TIER_ORDER: Record<AgentTier, number> = { meta: 0, coordinator: 1, worker: 2 };

export function sortAgentsForMatrix(
  members: KanbanTeamMember[],
  sessions: any[]  // useAllSessions() 的返回值
): KanbanTeamMember[] {
  const sessionMap = new Map(sessions.map(s => [s.id, s]));

  return [...members].sort((a, b) => {
    const tierA = TIER_ORDER[getAgentTier(a.roleId)];
    const tierB = TIER_ORDER[getAgentTier(b.roleId)];
    if (tierA !== tierB) return tierA - tierB;

    const session_a = sessionMap.get(a.sessionId);
    const session_b = sessionMap.get(b.sessionId);
    const presA = session_a ? getAgentPresenceVisual(session_a) : { dead: true, inactive: true };
    const presB = session_b ? getAgentPresenceVisual(session_b) : { dead: true, inactive: true };

    const statusA = presA.dead ? 2 : presA.inactive ? 1 : 0;
    const statusB = presB.dead ? 2 : presB.inactive ? 1 : 0;
    if (statusA !== statusB) return statusA - statusB;

    return (a.displayName || '').localeCompare(b.displayName || '');
  });
}
```

