### 4. 网格推荐算法（可直接复制）

```typescript
// sources/hooks/useMatrixLayout.ts

import { useWindowDimensions } from 'react-native';

interface GridConfig {
  rows: number;
  cols: number;
}

const TASK_STRIP_WIDTH = 140;  // 桌面端左栏宽度
const GRID_PRESETS: GridConfig[] = [
  { rows: 2, cols: 2 },
  { rows: 2, cols: 3 },
  { rows: 3, cols: 3 },
  { rows: 3, cols: 4 },
  { rows: 4, cols: 3 },
  { rows: 2, cols: 4 },
];

export function recommendGrid(agentCount: number, screenWidth: number): GridConfig {
  const minCellWidth = screenWidth > 768 ? 220 : 180;
  const availableWidth = screenWidth - TASK_STRIP_WIDTH;
  const maxCols = Math.max(2, Math.floor(availableWidth / minCellWidth));

  const candidates = GRID_PRESETS
    .filter(g => g.cols <= maxCols && g.rows * g.cols >= agentCount)
    .sort((a, b) => (a.rows * a.cols) - (b.rows * b.cols));

  return candidates[0] || { rows: Math.ceil(agentCount / maxCols), cols: maxCols };
}

export function useMatrixLayout(agentCount: number) {
  const { width } = useWindowDimensions();
  return recommendGrid(agentCount, width);
}
```

